Object.assign(window.I18N,{"Wer hat dich am meisten angegriffen?": "Kto atakował cię najczęściej?", "niemand besonders": "nikt szczególnie", "konnte von einem Angriff auf {0} nicht ablassen, obwohl er dort deutlich mehr verlor als gewann": "nie potrafił zrezygnować z ataku na {0}, choć tracił tam znacznie więcej, niż zyskiwał", "Sunk-Cost-Effekt": "efekt utopionych kosztów", "Verlustaversion": "awersja do strat", "Vergeltungsimpuls": "impuls odwetu", "Impulsives Schnelldenken": "impulsywne szybkie myślenie", "Feindseligkeitsverzerrung": "wrogie błędy atrybucji", "Introspektionsillusion": "złudzenie introspekcji", "Selbstwertdienliche Verzerrung": "efekt autoafirmacji", "Kognitive Verzerrung – Erklärung öffnen": "Błąd poznawczy – otwórz wyjaśnienie", "Psychologie": "Psychologia"});
